109:                 TypeSerializer<K> keySerializer, int numberOfKeyGroups,
110:                 KeyGroupRange keyGroupRange, TaskKvStateRegistry kvStateRegistry,
111:                 TtlTimeProvider ttlTimeProvider, MetricGroup metricGroup,
112:                 Collection<KeyedStateHandle> stateHandles, CloseableRegistry cancelStreamRegistry) {
