114:             this.jobID = jobID;
115:             this.operatorIdentifier = operatorIdentifier;
116:             this.keySerializer = keySerializer;
117:             this.numberOfKeyGroups = numberOfKeyGroups;
118:             this.keyGroupRange = keyGroupRange;
