28: import org.apache.flink.runtime.io.network.partition.DataBuffer;
29: import org.apache.flink.runtime.io.network.partition.hybrid.tiered.common.TieredStorageSubpartitionId;
30: 
31: import javax.annotation.Nullable;
32: 
33: import java.io.IOException;
34: import java.nio.ByteBuffer;
35: import java.util.Collections;
36: import java.util.LinkedList;
37: import java.util.List;
38: import java.util.function.BiConsumer;
39: 
40: import static org.apache.flink.util.Preconditions.checkNotNull;
41: import static org.apache.flink.util.Preconditions.checkState;
42: 
43: /**
44:  * The sort-based implementation of the {@link BufferAccumulator}. The {@link BufferAccumulator}
45:  * receives the records from {@link TieredStorageProducerClient} and the records will accumulate and
46:  * transform to finished buffers. The accumulated buffers will be transferred to the corresponding
47:  * tier dynamically.
48:  *
49:  * <p>The {@link SortBufferAccumulator} can help use less buffers to accumulate data, which
50:  * decouples the buffer usage with the number of parallelism. The number of buffers used by the
51:  * {@link SortBufferAccumulator} will be numBuffers at most. Once the {@link DataBuffer} is full, or
52:  * switching from broadcast to non-broadcast(or vice versa), the buffer in the sort buffer will be
53:  * flushed to the tiers.
54:  *
55:  * <p>Note that this class need not be thread-safe, because it should only be accessed from the main
56:  * thread.
57:  */
58: public class SortBufferAccumulator implements BufferAccumulator {
59: 
60:     /** The number of the subpartitions. */
61:     private final int numSubpartitions;
62: 
63:     /** The total number of the buffers used by the {@link SortBufferAccumulator}. */
64:     private final int numBuffers;
65: 
66:     /** The byte size of one single buffer. */
67:     private final int bufferSizeBytes;
68: 
69:     /** The empty buffers without storing data. */
70:     private final LinkedList<MemorySegment> freeSegments = new LinkedList<>();
71: 
72:     /** The memory manager of the tiered storage. */
73:     private final TieredStorageMemoryManager memoryManager;
74: 
75:     /**
76:      * The {@link DataBuffer} is utilized to accumulate the incoming records. Whenever there is a
77:      * transition from broadcast to non-broadcast (or vice versa), the buffer is flushed to ensure
78:      * data integrity. Note that this can be null before using it to store records, and this {@link
79:      * DataBuffer} will be released once flushed.
80:      */
81:     @Nullable private DataBuffer currentDataBuffer;
82: 
83:     /**
84:      * The buffer recycler. Note that this can be null before requesting buffers from the memory
85:      * manager.
86:      */
87:     @Nullable private BufferRecycler bufferRecycler;
88: 
89:     /**
90:      * The {@link SortBufferAccumulator}'s accumulated buffer flusher is not prepared during
91:      * construction, requiring the field to be initialized during setup. Therefore, it is necessary
92:      * to verify whether this field is null before using it.
93:      */
94:     @Nullable
95:     private BiConsumer<TieredStorageSubpartitionId, List<Buffer>> accumulatedBufferFlusher;
96: 
97:     /** Whether the current {@link DataBuffer} is a broadcast sort buffer. */
98:     private boolean isBroadcastDataBuffer;
99: 
100:     public SortBufferAccumulator(
101:             int numSubpartitions,
102:             int numBuffers,
103:             int bufferSizeBytes,
104:             TieredStorageMemoryManager memoryManager) {
105:         this.numSubpartitions = numSubpartitions;
106:         this.bufferSizeBytes = bufferSizeBytes;
107:         this.numBuffers = numBuffers;
108:         this.memoryManager = memoryManager;
109:     }
110: 
111:     @Override
112:     public void setup(BiConsumer<TieredStorageSubpartitionId, List<Buffer>> bufferFlusher) {
113:         this.accumulatedBufferFlusher = bufferFlusher;
114:     }
115: 
116:     @Override
117:     public void receive(
118:             ByteBuffer record,
119:             TieredStorageSubpartitionId subpartitionId,
120:             Buffer.DataType dataType,
121:             boolean isBroadcast)
122:             throws IOException {
123:         int targetSubpartition = subpartitionId.getSubpartitionId();
124:         switchCurrentDataBufferIfNeeded(isBroadcast);
125:         if (!checkNotNull(currentDataBuffer).append(record, targetSubpartition, dataType)) {
126:             return;
127:         }
128: 
129:         // The sort buffer is empty, but we failed to write the record into it, which indicates the
130:         // record is larger than the sort buffer can hold. So the record is written into multiple
131:         // buffers directly.
132:         if (!currentDataBuffer.hasRemaining()) {
133:             currentDataBuffer.release();
134:             writeLargeRecord(record, targetSubpartition, dataType);
135:             return;
136:         }
137: 
138:         flushDataBuffer();
139:         checkState(record.hasRemaining(), "Empty record.");
140:         receive(record, subpartitionId, dataType, isBroadcast);
141:     }
142: 
143:     @Override
144:     public void close() {
145:         flushCurrentDataBuffer();
146:         releaseFreeBuffers();
147:         if (currentDataBuffer != null) {
148:             currentDataBuffer.release();
149:         }
150:     }
151: 
152:     // ------------------------------------------------------------------------
153:     //  Internal Methods
154:     // ------------------------------------------------------------------------
155: 
156:     private void switchCurrentDataBufferIfNeeded(boolean isBroadcast) {
157:         if (isBroadcast == isBroadcastDataBuffer
158:                 && currentDataBuffer != null
159:                 && !currentDataBuffer.isReleased()
160:                 && !currentDataBuffer.isFinished()) {
161:             return;
162:         }
163:         isBroadcastDataBuffer = isBroadcast;
164:         flushCurrentDataBuffer();
165:         currentDataBuffer = createNewDataBuffer();
166:     }
167: 
168:     private DataBuffer createNewDataBuffer() {
169:         requestBuffers();
170: 
171:         // Use the half of the buffers for writing, and the other half for reading
172:         int numBuffersForSort = freeSegments.size() / 2;
173:         return new TieredStorageSortBuffer(
174:                 freeSegments,
175:                 this::recycleBuffer,
176:                 numSubpartitions,
177:                 bufferSizeBytes,
178:                 numBuffersForSort);
179:     }
180: 
181:     private void requestBuffers() {
182:         while (freeSegments.size() < numBuffers) {
183:             Buffer buffer = requestBuffer();
184:             freeSegments.add(checkNotNull(buffer).getMemorySegment());
185:             if (bufferRecycler == null) {
186:                 bufferRecycler = buffer.getRecycler();
187:             }
188:         }
189:     }
190: 
191:     private void flushDataBuffer() {
192:         if (currentDataBuffer == null
193:                 || currentDataBuffer.isReleased()
194:                 || !currentDataBuffer.hasRemaining()) {
195:             return;
196:         }
197:         currentDataBuffer.finish();
198: 
199:         do {
200:             MemorySegment freeSegment = getFreeSegment();
201:             BufferWithChannel bufferWithChannel = currentDataBuffer.getNextBuffer(freeSegment);
202:             if (bufferWithChannel == null) {
203:                 break;
204:             }
205:             flushBuffer(bufferWithChannel);
206:         } while (true);
207: 
208:         releaseFreeBuffers();
209:         currentDataBuffer.release();
210:     }
211: 
212:     private void flushCurrentDataBuffer() {
213:         if (currentDataBuffer != null) {
214:             flushDataBuffer();
215:             currentDataBuffer = null;
216:         }
217:     }
218: 
219:     private void writeLargeRecord(ByteBuffer record, int subpartitionId, Buffer.DataType dataType) {
220: 
221:         checkState(dataType != Buffer.DataType.EVENT_BUFFER);
222:         while (record.hasRemaining()) {
223:             int toCopy = Math.min(record.remaining(), bufferSizeBytes);
224:             MemorySegment writeBuffer = requestBuffer().getMemorySegment();
225:             writeBuffer.put(0, record, toCopy);
226: 
227:             flushBuffer(
228:                     new BufferWithChannel(
229:                             new NetworkBuffer(
230:                                     writeBuffer, checkNotNull(bufferRecycler), dataType, toCopy),
231:                             subpartitionId));
232:         }
233: 
234:         releaseFreeBuffers();
235:     }
236: 
237:     private MemorySegment getFreeSegment() {
238:         MemorySegment freeSegment = freeSegments.poll();
239:         if (freeSegment == null) {
240:             freeSegment = requestBuffer().getMemorySegment();
241:         }
242:         return freeSegment;
243:     }
244: 
245:     private void flushBuffer(BufferWithChannel bufferWithChannel) {
246:         checkNotNull(accumulatedBufferFlusher)
247:                 .accept(
248:                         new TieredStorageSubpartitionId(bufferWithChannel.getChannelIndex()),
249:                         Collections.singletonList(bufferWithChannel.getBuffer()));
250:     }
251: 
252:     private Buffer requestBuffer() {
253:         BufferBuilder bufferBuilder = memoryManager.requestBufferBlocking(this);
254:         BufferConsumer bufferConsumer = bufferBuilder.createBufferConsumerFromBeginning();
255:         Buffer buffer = bufferConsumer.build();
256:         bufferBuilder.close();
257:         bufferConsumer.close();
258:         return buffer;
259:     }
