85:      * The buffer recycler. Note that this can be null before requesting buffers from the memory
86:      * manager.
87:      */
88:     @Nullable
89:     private BufferRecycler bufferRecycler;
90: 
91:     /**
92:      * The {@link SortBufferAccumulator}'s accumulated buffer flusher is not prepared during
93:      * construction, requiring the field to be initialized during setup. Therefore, it is necessary
94:      * to verify whether this field is null before using it.
95:      */
96:     @Nullable
97:     private BiConsumer<TieredStorageDataSubpartitionId, List<Buffer>> accumulatedBufferFlusher;
98: 
99:     /** Whether the current {@link DataBuffer} is a broadcast sort buffer. */
100:     private boolean isBroadcastDataBuffer;
101: 
102:     public SortBufferAccumulator(
103:             int numSubpartitions,
104:             int numBuffers,
105:             int bufferSizeBytes,
106:             TieredStorageMemoryManager memoryManager) {
107:         this.numSubpartitions = numSubpartitions;
108:         this.bufferSizeBytes = bufferSizeBytes;
109:         this.numBuffers = numBuffers;
110:         this.memoryManager = memoryManager;
111:     }
112: 
113:     @Override
114:     public void setup(BiConsumer<TieredStorageDataSubpartitionId, List<Buffer>> bufferFlusher) {
115:         this.accumulatedBufferFlusher = bufferFlusher;
116:     }
117: 
118:     @Override
119:     public void receive(
120:             ByteBuffer record,
121:             TieredStorageDataSubpartitionId subpartitionId,
122:             Buffer.DataType dataType,
123:             boolean isBroadcast)
124:             throws IOException {
125:         int targetSubpartition = subpartitionId.getSubpartitionId();
126:         switchCurrentDataBufferIfNeeded(isBroadcast);
127:         if (!checkNotNull(currentDataBuffer).append(record, targetSubpartition, dataType)) {
128:             return;
129:         }
130: 
131:         // The sort buffer is empty, but we failed to write the record into it, which indicates the
132:         // record is larger than the sort buffer can hold. So the record is written into multiple
133:         // buffers directly.
134:         if (!currentDataBuffer.hasRemaining()) {
135:             currentDataBuffer.release();
136:             writeLargeRecord(record, targetSubpartition, dataType);
137:             return;
138:         }
139: 
140:         flushDataBuffer();
141:         checkState(record.hasRemaining(), "Empty record.");
142:         receive(record, subpartitionId, dataType, isBroadcast);
143:     }
144: 
145:     @Override
146:     public void close() {
147:         flushCurrentDataBuffer();
148:         releaseFreeBuffers();
149:         if (currentDataBuffer != null) {
150:             currentDataBuffer.release();
151:         }
152:     }
153: 
154:     // ------------------------------------------------------------------------
155:     //  Internal Methods
156:     // ------------------------------------------------------------------------
157: 
158:     private void switchCurrentDataBufferIfNeeded(boolean isBroadcast) {
159:         if (isBroadcast == isBroadcastDataBuffer
160:                 && currentDataBuffer != null
161:                 && !currentDataBuffer.isReleased()
162:                 && !currentDataBuffer.isFinished()) {
163:             return;
164:         }
165:         isBroadcastDataBuffer = isBroadcast;
166:         flushCurrentDataBuffer();
167:         currentDataBuffer = createNewDataBuffer();
168:     }
169: 
170:     private DataBuffer createNewDataBuffer() {
171:         requestBuffers();
172: 
173:         // Use the half of the buffers for writing, and the other half for reading
174:         int numBuffersForSort = freeSegments.size() / 2;
175:         return new TieredStorageSortBuffer(
176:                 freeSegments,
177:                 this::recycleBuffer,
178:                 numSubpartitions,
179:                 bufferSizeBytes,
180:                 numBuffersForSort);
181:     }
182: 
183:     private void requestBuffers() {
184:         while (freeSegments.size() < numBuffers) {
185:             Buffer buffer = requestBuffer();
186:             freeSegments.add(checkNotNull(buffer).getMemorySegment());
187:             if (bufferRecycler == null) {
188:                 bufferRecycler = buffer.getRecycler();
189:             }
190:         }
191:     }
192: 
193:     private void flushDataBuffer() {
194:         if (currentDataBuffer == null
195:                 || currentDataBuffer.isReleased()
196:                 || !currentDataBuffer.hasRemaining()) {
197:             return;
198:         }
199:         currentDataBuffer.finish();
200: 
201:         do {
202:             MemorySegment freeSegment = getFreeSegment();
203:             BufferWithDataChannel bufferWithChannel = currentDataBuffer.getNextBuffer(freeSegment);
204:             if (bufferWithChannel == null) {
205:                 break;
206:             }
207:             flushBuffer(bufferWithChannel);
208:         } while (true);
209: 
210:         releaseFreeBuffers();
211:         currentDataBuffer.release();
212:     }
213: 
214:     private void flushCurrentDataBuffer() {
215:         if (currentDataBuffer != null) {
216:             flushDataBuffer();
217:             currentDataBuffer = null;
218:         }
219:     }
220: 
221:     private void writeLargeRecord(ByteBuffer record, int subpartitionId, Buffer.DataType dataType) {
222: 
223:         checkState(dataType != Buffer.DataType.EVENT_BUFFER);
224:         while (record.hasRemaining()) {
225:             int toCopy = Math.min(record.remaining(), bufferSizeBytes);
226:             MemorySegment writeBuffer = requestBuffer().getMemorySegment();
227:             writeBuffer.put(0, record, toCopy);
228: 
229:             flushBuffer(
230:                     new BufferWithDataChannel(
231:                             new NetworkBuffer(
232:                                     writeBuffer, checkNotNull(bufferRecycler), dataType, toCopy),
233:                             subpartitionId));
234:         }
235: 
236:         releaseFreeBuffers();
237:     }
238: 
239:     private MemorySegment getFreeSegment() {
240:         MemorySegment freeSegment = freeSegments.poll();
241:         if (freeSegment == null) {
242:             freeSegment = requestBuffer().getMemorySegment();
243:         }
244:         return freeSegment;
245:     }
246: 
247:     private void flushBuffer(BufferWithDataChannel bufferWithChannel) {
248:         checkNotNull(accumulatedBufferFlusher)
249:                 .accept(
250:                         new TieredStorageDataSubpartitionId(bufferWithChannel.getChannelIndex()),
251:                         Collections.singletonList(bufferWithChannel.getBuffer()));
252:     }
253: 
254:     private Buffer requestBuffer() {
255:         BufferBuilder bufferBuilder = memoryManager.requestBufferBlocking(this);
256:         BufferConsumer bufferConsumer = bufferBuilder.createBufferConsumerFromBeginning();
257:         Buffer buffer = bufferConsumer.build();
258:         bufferBuilder.close();
259:         bufferConsumer.close();
260:         return buffer;
261:     }
262: 
263:     private void releaseFreeBuffers() {
264:         freeSegments.forEach(this::recycleBuffer);
265:         freeSegments.clear();
266:     }
267: 
268:     private void recycleBuffer(MemorySegment memorySegment) {
269:         checkNotNull(bufferRecycler).recycle(memorySegment);
270:     }
